// MIT. Conditions from original runtime snapshots; no parallel traffic collector.
import {randomUUID} from 'node:crypto';
import {activeIncident, kinds, merchantBinding} from './incident-config.mjs';
import {queueNotification, terminalNotification} from './notifications.mjs';

const cumulative=['started','completed','responses','success','challenge','clientError','serverError','other','disconnected'];
const iso=now=>new Date(now).toISOString();
export function freshMerchant(config,merchant) {
  return {binding:merchantBinding(config,merchant),previous:null,lastSuccessAt:null,lastAttemptAt:null,
    lastCapture:null,captureState:'NO_CAPTURE',sessionsSeen:0,lastError:null,conditions:{}};
}
export function updateConfiguration(state,config,digest,env,now) {
  const merchants={};
  for(const merchant of config.merchants) {
    const old=state.merchants[merchant.id],binding=merchantBinding(config,merchant);
    merchants[merchant.id]=old?.binding===binding?old:freshMerchant(config,merchant);
  }
  for(const incident of state.incidents.filter(activeIncident)) {
    if(merchants[incident.merchantId]?.binding===incident.binding) continue;
    incident.status='RETIRED';incident.retiredReason='CONFIGURATION_CHANGED';
    incident.closedAt=iso(now);incident.updatedAt=iso(now);incident.revision++;
    // Bind this final old-source transition to its original configuration.
    queueNotification(state,incident,'RETIRED',env,now);
  }
  state.config=config;state.configHash=digest;state.configRevision++;
  state.merchants=merchants;
}
function signalsFor(config,merchant,observation,previous,now) {
  const packet=observation.packet;
  if(!packet) return {signals:{ENDPOINT_UNAVAILABLE:{bad:true,values:{}}},error:observation.error};
  const o=packet.report.observation,captured=Date.parse(o.capturedAt),start=Date.parse(o.startedAt);
  const same=previous?.sessionId===o.sessionId;
  if(start>captured || captured>now+5000 || now-captured>30_000 ||
      (same&&(previous.startedAt!==o.startedAt||captured<Date.parse(previous.capturedAt)||
        cumulative.some(key=>o.totals[key]<previous.totals[key])||o.observerErrors<previous.observerErrors)))
    return {signals:{ENDPOINT_UNAVAILABLE:{bad:true,values:{}}},error:'SOURCE_COUNTER_OR_CLOCK_INVALID'};
  const minute=Math.floor(captured/60_000)*60_000;
  const windowStart=minute-(config.windowMinutes-1)*60_000;
  const buckets=o.minutes.filter(row=>Date.parse(row.minute)>=windowStart&&Date.parse(row.minute)<=minute);
  if(buckets.length!==config.windowMinutes || new Set(buckets.map(row=>row.minute)).size!==buckets.length ||
      buckets.some(row=>Date.parse(row.minute)%60_000!==0))
    return {signals:{ENDPOINT_UNAVAILABLE:{bad:true,values:{}}},error:'SOURCE_MINUTE_WINDOW_INVALID'};
  const totals=buckets.reduce((sum,row)=>{for(const key of ['responses','completed','serverError','disconnected'])sum[key]+=row[key];return sum;},
    {responses:0,completed:0,serverError:0,disconnected:0});
  const complete=o.attached&&o.observerErrors===0&&start<=windowStart;
  const traffic=(threshold,failures,requests)=>{
    if(!threshold)return {bad:null,values:{}};
    const percent=requests?failures*100/requests:0;
    const bad=failures>=threshold.minimum&&percent>=threshold.percent;
    return {bad:bad?true:complete?false:null,values:{requests,failures,percent,
      minimum:threshold.minimum,thresholdPercent:threshold.percent,windowMinutes:config.windowMinutes}};
  };
  const signals={ENDPOINT_UNAVAILABLE:{bad:false,values:{}},
    OBSERVER_INCOMPLETE:{bad:!o.attached||o.observerErrors>0,values:{observerErrors:o.observerErrors}},
    HTTP_5XX:traffic(config.httpErrors,totals.serverError,totals.responses),
    DISCONNECTED:traffic(config.disconnects,totals.disconnected,totals.completed)};
  if(merchant.delivery) {
    const d=observation.delivery;
    const available=d?.available===true;
    signals.DELIVERY_UNAVAILABLE={bad:available?false:merchant.delivery.required?true:null,values:{}};
    signals.DELIVERY_BACKLOG={bad:available?d.pending>0&&d.oldestPendingSeconds!==null&&
      d.oldestPendingSeconds>=merchant.delivery.oldestPendingSeconds:null,
      values:available?{pending:d.pending,oldestPendingSeconds:d.oldestPendingSeconds ?? 0,
        thresholdSeconds:merchant.delivery.oldestPendingSeconds}:{}};
    signals.DELIVERY_EXHAUSTED={bad:available?d.exhausted>=merchant.delivery.exhausted:null,
      values:available?{exhausted:d.exhausted,minimum:merchant.delivery.exhausted}:{}};
  }
  return {signals,packet,previous:{sessionId:o.sessionId,startedAt:o.startedAt,capturedAt:o.capturedAt,
    observerErrors:o.observerErrors,totals:Object.fromEntries(cumulative.map(key=>[key,o.totals[key]]))},
    window:{from:iso(windowStart),through:o.capturedAt,complete,sessionStartedAt:o.startedAt},error:null};
}
export function validateDelivery(value,now) {
  if(value?.schema!=='stellar-forge.sf98.operator-delivery.v1'||typeof value.available!=='boolean')
    throw new Error('SF93_DELIVERY_SOURCE_INVALID');
  if(!value.available)return {available:false};
  const fields=['originalNativeEvents','webhookAccepted','pending','retryDue','retryWaiting','exhausted'];
  if(fields.some(key=>!Number.isSafeInteger(value[key])||value[key]<0)||
      value.originalNativeEvents!==value.webhookAccepted+value.pending+value.exhausted||
      value.retryDue+value.retryWaiting!==value.pending ||
      !(value.oldestPendingSeconds===null||Number.isSafeInteger(value.oldestPendingSeconds)&&value.oldestPendingSeconds>=0)||
      !Number.isFinite(Date.parse(value.capturedAt))||Date.parse(value.capturedAt)>now+5000||
      now-Date.parse(value.capturedAt)>30_000) throw new Error('SF93_DELIVERY_SOURCE_INVALID');
  return {available:true,capturedAt:value.capturedAt,
    ...Object.fromEntries(fields.map(key=>[key,value[key]])),oldestPendingSeconds:value.oldestPendingSeconds};
}
export async function applyObservation(state,merchant,observation,saveCapture,env,now) {
  const row=state.merchants[merchant.id];
  const result=signalsFor(state.config,merchant,observation,row.previous,now);
  row.lastAttemptAt=iso(now);row.lastError=result.error ?? null;
  let currentCapture;
  const capture=async()=>{
    if(currentCapture!==undefined)return currentCapture;
    currentCapture=result.packet?await saveCapture(result.packet):null;
    row.captureState=currentCapture?'CAPTURED':result.packet?'STORAGE_LIMIT':'SOURCE_UNAVAILABLE';
    if(currentCapture)row.lastCapture=currentCapture;
    return currentCapture;
  };
  if(result.packet) {
    const changedSession=row.previous?.sessionId!==result.previous.sessionId;
    if(changedSession) {
      row.sessionsSeen++;
      // A new native observer starts a new history. No cumulative subtraction.
      for(const condition of Object.values(row.conditions)) {condition.badStreak=0;condition.goodStreak=0;}
    }
    row.previous=result.previous;row.lastSuccessAt=iso(now);row.window=result.window;
    if(!row.lastCapture||changedSession||now-Date.parse(row.lastCapture.generatedAt)>=state.config.captureEveryMs) await capture();
  }
  for(const kind of kinds) {
    const condition=row.conditions[kind]??={badStreak:0,goodStreak:0,lastState:'UNKNOWN',incidentId:null};
    const signal=result.signals[kind]??{bad:null,values:{}};
    condition.lastState=signal.bad===null?'UNKNOWN':signal.bad?'FAILING':'CLEAR';
    if(signal.bad===null) {condition.badStreak=0;condition.goodStreak=0;continue;}
    condition.badStreak=signal.bad?Math.min(100,condition.badStreak+1):0;
    condition.goodStreak=signal.bad?0:Math.min(100,condition.goodStreak+1);
    let incident=state.incidents.find(item=>item.id===condition.incidentId&&activeIncident(item));
    if(signal.bad) {
      if(!incident&&condition.badStreak>=state.config.failurePolls) {
        const before=result.packet?await capture():row.lastCapture;
        incident={id:randomUUID(),merchantId:merchant.id,merchantLabel:merchant.label,binding:row.binding,kind,
          status:'OPEN',revision:1,openedAt:iso(now),updatedAt:iso(now),lastObservedAt:iso(now),closedAt:null,
          sessionId:row.previous?.sessionId ?? null,lastSessionId:row.previous?.sessionId ?? null,
          signal:{...signal.values,consecutivePolls:condition.badStreak},
          acknowledgment:null,beforeCapture:before ?? null,afterCapture:null,notificationState:null};
        state.incidents.push(incident);condition.incidentId=incident.id;
        queueNotification(state,incident,'OPENED',env,now);
      } else if(incident) {
        incident.lastObservedAt=iso(now);incident.signal={...signal.values,consecutivePolls:condition.badStreak};
        incident.lastSessionId=row.previous?.sessionId ?? null;
      }
    } else if(incident&&condition.goodStreak>=state.config.recoveryPolls) {
      incident.status='RECOVERED';incident.closedAt=iso(now);incident.updatedAt=iso(now);incident.revision++;
      incident.afterCapture=await capture();incident.recoverySessionId=row.previous?.sessionId ?? null;
      incident.recoverySignal={...signal.values,consecutivePolls:condition.goodStreak};
      queueNotification(state,incident,'RECOVERED',env,now);condition.incidentId=null;
    }
  }
}
export function pruneRecords(state,now) {
  const keepEvents=new Set(state.notifications.filter(event=>!terminalNotification(event)).map(event=>event.id));
  state.notifications.filter(terminalNotification).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))
    .slice(0,state.config.retention.notifications).forEach(event=>keepEvents.add(event.id));
  state.notifications=state.notifications.filter(event=>keepEvents.has(event.id));
  const protectedIds=new Set(state.notifications.filter(event=>!terminalNotification(event)).map(event=>event.incidentId));
  const cutoff=now-state.config.retention.closedDays*86_400_000;
  const closed=state.incidents.filter(item=>!activeIncident(item)&&Date.parse(item.closedAt)>=cutoff)
    .sort((a,b)=>b.closedAt.localeCompare(a.closedAt)).slice(0,state.config.retention.closedIncidents);
  const keep=new Set(closed.map(item=>item.id));
  state.incidents=state.incidents.filter(item=>activeIncident(item)||protectedIds.has(item.id)||keep.has(item.id));
  const ids=new Set(state.incidents.map(item=>item.id));
  state.notifications=state.notifications.filter(event=>ids.has(event.incidentId));
}

// MIT. Human operator changes and original SF74 support-file handoff.
import {mkdir,writeFile} from 'node:fs/promises';
import {resolve,join} from 'node:path';
import {compileConfig,configHash,activeIncident} from './incident-config.mjs';
import {openIncidentStore,readPrivateFile,statusView} from './incident-store.mjs';
import {updateConfiguration,pruneRecords} from './incident-model.mjs';
import {queueNotification,destinationForEvent,MAX_PENDING,terminalNotification,updateIncidentNotificationState} from './notifications.mjs';
import {parseWorkspace,MAX_WORKSPACE_BYTES} from '../sf74-merchant-support-console/workspace-file.mjs';
import {inspectRuntimeFiles,exportRuntimeHandoff,RUNTIME_SCHEMA} from '../sf74-merchant-support-console/runtime-support.mjs';
import {caseMetadata} from '../sf74-merchant-support-console/case-store.mjs';

const fail=code=>{throw new Error('SF93_'+code);};
const note=value=>{
  if(typeof value!=='string'||Buffer.byteLength(value)>2000||
      /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value)||Buffer.from(value).toString('utf8')!==value)fail('NOTE_INVALID');
  return value;
};
function owner(value) {
  if(!value?.trim()||Buffer.byteLength(value)>160||/[\r\n\t]/.test(value))fail('OPERATOR_REQUIRED');
  return note(value);
}
function selectedIncident(state,id,revision) {
  const item=state.incidents.find(row=>row.id===id);
  if(!item)fail('INCIDENT_NOT_FOUND');
  if(!Number.isSafeInteger(revision)||revision!==item.revision)fail('INCIDENT_REVISION_CONFLICT');
  return item;
}
export async function configureIncidents({directory,config,expectedConfigRevision,environment=process.env}) {
  const normalized=compileConfig(config),store=await openIncidentStore(directory);
  return store.transaction(state=>{
    if(expectedConfigRevision!==state.configRevision)fail('CONFIGURATION_REVISION_CONFLICT');
    const digest=configHash(normalized);
    if(digest!==state.configHash)updateConfiguration(state,normalized,digest,environment,Date.now());
    return {configRevision:state.configRevision,configHash:state.configHash};
  });
}
export async function acknowledgeIncident({directory,id,expectedRevision,by,notes='',environment=process.env}) {
  by=owner(by);notes=note(notes);const store=await openIncidentStore(directory);
  return store.transaction(state=>{
    const incident=selectedIncident(state,id,expectedRevision);
    if(incident.status!=='OPEN')fail('INCIDENT_NOT_OPEN');
    const now=Date.now(),at=new Date(now).toISOString();
    incident.status='ACKNOWLEDGED';incident.revision++;incident.updatedAt=at;
    incident.acknowledgment={by,notes,at};queueNotification(state,incident,'ACKNOWLEDGED',environment,now);
    return structuredClone(incident);
  });
}
export async function remindIncident({directory,id,expectedRevision,expectedNotificationId,environment=process.env}) {
  const store=await openIncidentStore(directory);
  return store.transaction(state=>{
    const incident=selectedIncident(state,id,expectedRevision);
    if(expectedNotificationId!==undefined) {
      if(expectedNotificationId!==null&&(typeof expectedNotificationId!=='string'||
          !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(expectedNotificationId)))
        fail('NOTIFICATION_EXPECTATION_INVALID');
      const latest=state.notifications.findLast(event=>event.incidentId===incident.id)?.id??null;
      if(latest!==expectedNotificationId)fail('NOTIFICATION_SELECTION_CONFLICT');
    }
    const event=queueNotification(state,incident,'REMINDER',environment,Date.now());
    return {incidentId:incident.id,eventId:event?.id ?? null,status:event?.status ?? incident.notificationIssue ?? incident.notificationState};
  });
}
export async function operateNotification({directory,id,expectedAttempts,action,by,environment=process.env}) {
  by=owner(by);const store=await openIncidentStore(directory);
  return store.transaction(state=>{
    const event=state.notifications.find(row=>row.id===id);
    if(!event)fail('NOTIFICATION_NOT_FOUND');
    if(expectedAttempts!==event.attempts)fail('NOTIFICATION_ATTEMPT_CONFLICT');
    if(event.status==='IN_FLIGHT')fail('NOTIFICATION_ATTEMPT_IN_FLIGHT');
    if(event.status==='DELIVERED'||event.status==='CANCELLED')fail('NOTIFICATION_ALREADY_FINISHED');
    if(!['retry','cancel'].includes(action))fail('NOTIFICATION_ACTION_INVALID');
    if(action==='cancel') {
      event.status='CANCELLED';event.lastReason='OPERATOR_CANCELLED';event.nextAttemptAt=null;
    } else {
      if(!['PAUSED','EXHAUSTED'].includes(event.status))fail('NOTIFICATION_ALREADY_SCHEDULED');
      const destination=destinationForEvent(state,event,environment);
      if(destination.reason)fail(destination.reason+'_USE_NOTIFY_FOR_A_NEW_DESTINATION');
      if(terminalNotification(event)&&state.notifications.filter(row=>!terminalNotification(row)).length>=MAX_PENDING)fail('NOTIFICATION_QUEUE_CAPACITY');
      const limit=event.attempts+state.config.notification.maxAttempts;
      if(limit>100_000)fail('NOTIFICATION_LIFETIME_ATTEMPT_LIMIT');
      event.status='RETRY';event.attemptLimit=limit;event.lastReason='OPERATOR_RETRY';event.nextAttemptAt=new Date().toISOString();
    }
    event.operatorAction={by,action,at:new Date().toISOString()};
    updateIncidentNotificationState(state,event);
    return {id:event.id,status:event.status,attempts:event.attempts,attemptLimit:event.attemptLimit};
  });
}
export async function pruneIncidents({directory}) {
  const store=await openIncidentStore(directory);
  return store.transaction(state=>{
    const before={incidents:state.incidents.length,notifications:state.notifications.length};
    pruneRecords(state,Date.now());
    return {removedIncidents:before.incidents-state.incidents.length,
      removedNotifications:before.notifications-state.notifications.length};
  });
}
export async function incidentStatus({directory,details=false}) {
  return statusView(await(await openIncidentStore(directory)).read(),{details});
}
export async function exportIncident({directory,id,expectedRevision,workspaceFile,routeId,out}) {
  const workspaceText=new TextDecoder('utf-8',{fatal:true}).decode(await readPrivateFile(resolve(workspaceFile),MAX_WORKSPACE_BYTES));
  const workspace=await parseWorkspace(workspaceText),store=await openIncidentStore(directory);
  const snapshot=await store.transaction(async(state,io)=>{
    const incident=selectedIncident(state,id,expectedRevision),files={};
    for(const side of ['before','after']) {
      const ref=incident[side+'Capture'];files[side]=ref?await io.readCapture(ref):null;
    }
    return {incident:structuredClone(incident),files};
  },{readonly:true});
  if(!snapshot.files.before&&!snapshot.files.after)fail('INCIDENT_HAS_NO_ORIGINAL_CAPTURE');
  const capture=files=>files?inspectRuntimeFiles({files:Object.fromEntries(Object.entries(files).map(([name,bytes])=>[name,bytes.toString('base64')])),
    inputs:workspace.inputs,routeId}).capture:null;
  const supportText=JSON.stringify({schema:RUNTIME_SCHEMA,before:capture(snapshot.files.before),after:capture(snapshot.files.after)},null,2)+'\n';
  const i=snapshot.incident,ack=i.acknowledgment;
  const metadata=caseMetadata({merchant:i.merchantLabel,owner:ack?.by ?? '',
    status:i.status==='RECOVERED'?'ready':activeIncident(i)?'in_progress':'waiting',followUpOn:'',
    nextAction:i.status==='RECOVERED'?'Review the recovered original seller capture in this case.':
      i.status==='RETIRED'?'Review the retired source registration and current merchant configuration.':'Resolve the active '+i.kind+' incident.',
    notes:`Original SF93 incident ${i.id}\nRegistered merchant: ${i.merchantId}\nCondition: ${i.kind}\nIncident state: ${i.status}\nOpened: ${i.openedAt}\nLast failing observation: ${i.lastObservedAt}\nClosed: ${i.closedAt ?? 'open'}\n`+
      (i.retiredReason?`Retirement: ${i.retiredReason}; this is not an observed recovery.\n`:'')+
      (ack?`Acknowledged: ${ack.at} by ${ack.by}\n${ack.notes}\n`:'No human acknowledgment recorded.\n')});
  const result=await exportRuntimeHandoff({workspaceText,supportText,metadata});
  const folder=resolve(out ?? '');if(!out||folder==='/'||folder===process.cwd())fail('NEW_EXPORT_DIRECTORY_REQUIRED');
  await mkdir(folder,{mode:0o700});
  const save=(path,bytes)=>writeFile(path,bytes,{flag:'wx',mode:0o600});
  await save(join(folder,'incident.json'),JSON.stringify(i,null,2)+'\n');
  await save(join(folder,'runtime-support.json'),supportText);
  await save(join(folder,'support-handoff.json'),result.handoff);
  await save(join(folder,'support.html'),result.html);
  for(const side of ['before','after'])if(snapshot.files[side]) {
    const path=join(folder,side);await mkdir(path,{mode:0o700});
    for(const [name,bytes] of Object.entries(snapshot.files[side]))await save(join(path,name),bytes);
  }
  return {out:folder,incidentId:i.id,revision:i.revision,comparison:result.report.comparison.state,
    captures:result.report.summary.captures,handoff:'support-handoff.json'};
}

// MIT. Private atomic incident state; original Linux kernel lease owns writes.
import {constants} from 'node:fs';
import {open,mkdir,lstat,readdir,rename,unlink} from 'node:fs/promises';
import {resolve,join} from 'node:path';
import {randomUUID} from 'node:crypto';
import {acquireStateLease} from '../merchant-fleet-gateway/state-lease.mjs';
import {compileConfig,configHash,hash,activeIncident,kinds} from './incident-config.mjs';
import {freshMerchant,pruneRecords} from './incident-model.mjs';
import {checkPayload} from './notifications.mjs';
import {slackTimestamp,validSlackReceipt,validSlackRequest} from './notifications-slack.mjs';

export const STATE_SCHEMA='stellar-forge.seller-incidents.v1';
const CAPTURE_SCHEMA='stellar-forge.seller-incident-capture.v1';
const MAX_STATE=16_777_216,MAX_CAPTURE=12_000_000;
const PACKET_FILES=['bundle.json','operator-brief.md','metrics.prom','manifest.json'];
const UUID=/^[a-f0-9-]{36}$/;
const CAPTURE=/^capture-([a-f0-9]{64})\.json$/;
const decoder=new TextDecoder('utf-8',{fatal:true});
const fail=code=>{throw new Error('SF93_'+code);};
const sleep=ms=>new Promise(done=>setTimeout(done,ms));
const privateStat=stat=>stat.isFile()&&!(stat.mode&0o077)&&stat.uid===process.getuid();

async function privateDirectory(path,create=false) {
  if(create)await mkdir(path,{mode:0o700}).catch(error=>{if(error.code!=='EEXIST')throw error;});
  const stat=await lstat(path);
  if(!stat.isDirectory()||stat.isSymbolicLink()||(stat.mode&0o077)||stat.uid!==process.getuid())fail('PRIVATE_DIRECTORY_REQUIRED');
}
export async function readPrivateFile(path,limit) {
  const file=await open(path,constants.O_RDONLY|constants.O_NOFOLLOW);
  try {
    const stat=await file.stat();
    if(!privateStat(stat)||stat.size>limit)fail('PRIVATE_BOUNDED_FILE_REQUIRED');
    const chunks=[];let size=0;
    for(;;) {
      const buffer=Buffer.alloc(Math.min(65_536,limit+1-size));
      const {bytesRead}=await file.read(buffer,0,buffer.length,null);
      if(!bytesRead)break;
      size+=bytesRead;if(size>limit)fail('FILE_SIZE_LIMIT');chunks.push(buffer.subarray(0,bytesRead));
    }
    return Buffer.concat(chunks);
  } finally {await file.close();}
}
async function writePrivate(path,bytes) {
  const file=await open(path,constants.O_CREAT|constants.O_EXCL|constants.O_WRONLY|constants.O_NOFOLLOW,0o600);
  try {await file.writeFile(bytes);await file.sync();}finally{await file.close();}
}
async function syncDirectory(path) {const file=await open(path,constants.O_RDONLY|constants.O_DIRECTORY);try{await file.sync();}finally{await file.close();}}
function decode(bytes) {try{return JSON.parse(decoder.decode(bytes));}catch{fail('PRIVATE_JSON_INVALID');}}
function validateState(state) {
  if(state?.schema!==STATE_SCHEMA||!Number.isSafeInteger(state.revision)||state.revision<1||
      !Number.isSafeInteger(state.configRevision)||state.configRevision<1||
      !state.merchants||typeof state.merchants!=='object'||Array.isArray(state.merchants)||
      !Array.isArray(state.incidents)||state.incidents.length>10_000||
      !Array.isArray(state.notifications)||state.notifications.length>4096)fail('STATE_INVALID');
  const config=compileConfig(state.config);
  if(configHash(config)!==state.configHash)fail('CONFIGURATION_DIGEST_MISMATCH');
  const incidents=new Set();
  if (state.slackCooldowns != null && (typeof state.slackCooldowns !== 'object' || Array.isArray(state.slackCooldowns) ||
      Object.keys(state.slackCooldowns).length > 128 || Object.entries(state.slackCooldowns).some(([key,value]) =>
        !/^[a-f0-9]{64}$/.test(key) || typeof value !== 'string' || !Number.isFinite(Date.parse(value)))))
    fail('SLACK_COOLDOWN_INVALID');
  for(const item of state.incidents) {
    if(!UUID.test(item.id??'')||incidents.has(item.id)||!kinds.includes(item.kind)||
        !['OPEN','ACKNOWLEDGED','RECOVERED','RETIRED'].includes(item.status)||
        !Number.isSafeInteger(item.revision)||item.revision<1)fail('INCIDENT_STATE_INVALID');
    const thread = item.notificationThread;
    if (thread != null && (!/^[a-f0-9]{64}$/.test(thread.notificationConfigHash ?? '') ||
        !/^[a-f0-9]{64}$/.test(thread.endpointHash ?? '') || !validSlackReceipt(thread.receipt)))
      fail('SLACK_THREAD_STATE_INVALID');
    incidents.add(item.id);
  }
  const events=new Set();
  for(const event of state.notifications) {
    if(!UUID.test(event.id??'')||events.has(event.id)||!incidents.has(event.incidentId)||
        !['PENDING','RETRY','IN_FLIGHT','PAUSED','DELIVERED','EXHAUSTED','CANCELLED'].includes(event.status)||
        !/^[a-f0-9]{64}$/.test(event.notificationConfigHash??'')||
        !Number.isSafeInteger(event.attempts)||event.attempts<0||event.attempts>100_000||
