    if(!Number.isSafeInteger(expectedConfigRevision)||expectedConfigRevision<1||
        typeof expectedConfigHash!=='string'||!/^[0-9a-f]{64}$/.test(expectedConfigHash))
      throw new Error('SF93_CONFIGURATION_EXPECTATION_INVALID');
  }
