        !SHA.test(value.sha256??'')||!Number.isSafeInteger(value.bytes)||value.bytes<1024||value.bytes>MAX_BUNDLE||
        !Array.isArray(value.parts)||!value.parts.length||value.parts.length>Math.ceil(MAX_BUNDLE/PART_BYTES)||
