      if(!/^[a-f0-9-]{36}\.json$/.test(name)||!UUID.test(name.slice(0,-5)))throw fail('DRAFT_CHANGED','Unexpected received draft record.');
      rows.push(await savedDraft(packageId,name.slice(0,-5)));
    }
