      basis:covered.some(row=>row.session.dayIndex===null)?'LEGACY_SESSION_AND_DAY':'EXACT_SESSION_DAY_ROUTE',
      sessionIds:covered.map(row=>row.session.sessionId),modes:[...new Set(covered.map(row=>row.session.mode))].sort(),
